import{_ as t,c as d,o,ae as c}from"./chunks/framework.CFeneB-q.js";const g=JSON.parse('{"title":"移动端 · 项目结构","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/project-structure.md","filePath":"mobile/project-structure.md","lastUpdated":1789438865000}'),a={name:"mobile/project-structure.md"};function s(r,e,i,n,p,l){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="移动端-·-项目结构" tabindex="-1">移动端 · 项目结构 <a class="header-anchor" href="#移动端-·-项目结构" aria-label="Permalink to &quot;移动端 · 项目结构&quot;">​</a></h1><blockquote><p>以 <code>delivery-template-uniapp</code> 为蓝本。原始版《目录结构详解》已迁入<a href="/E9-Front-Dev-Guide.io/mobile/references/directory-structure.html">参考文档</a>，本文以其为底稿并修正了与当前代码的偏差（分包已从 4 个演进为 9 个、主包瘦身等）。</p></blockquote><h2 id="顶层目录职责" tabindex="-1">顶层目录职责 <a class="header-anchor" href="#顶层目录职责" aria-label="Permalink to &quot;顶层目录职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>职责</th></tr></thead><tbody><tr><td><code>api/</code></td><td>全局公共 API（6 文件）：user / dept / dict / equipment / subitem / common</td></tr><tr><td><code>components/</code></td><td>自研 <code>pap-*</code> 业务组件族（14 个）+ app-upgrade、message-banner，easycom 自动注册</td></tr><tr><td><code>config/</code></td><td>仅 <code>index.js</code>：按平台与环境选 baseURL + 三方密钥（高德 / TPLink / 乐橙 / OSS）</td></tr><tr><td><code>constants/</code></td><td>仅 <code>permissions.js</code>：<code>definePermission()</code> 生成 13 种标准按钮权限码</td></tr><tr><td><code>libs/</code></td><td>三方库本地离线包：dayjs、echarts 5.6.1、timezone、utc（不走 npm）</td></tr><tr><td><code>locale/</code></td><td>i18n 词典：<code>AppLang.js</code>（聚合入口）+ <code>zh.js</code>（约 113 条）+ <code>en.js</code>（约 127 条）</td></tr><tr><td><code>pages/</code></td><td><strong>主包页面</strong>，当前仅 <code>index/</code>（index.vue + lang.js，即首页/功能入口）</td></tr><tr><td><code>subPages/</code></td><td>分包页面实体（9 个分包，122 页，见下）</td></tr><tr><td><code>static/</code></td><td>仅 <code>images/</code>（common / index / mine / navbar / notice / quality 图标）</td></tr><tr><td><code>styles/</code></td><td><code>index.scss</code>（全局 page 样式）+ <code>mixin.scss</code>（to-rpx、gap 兼容）</td></tr><tr><td><code>utils/</code></td><td>14 个工具模块：request、prefix-rules、auth、cache、md5、permissions、version-manager、logout、mixin（i18n）、uview（桥接）等</td></tr><tr><td><code>uni_modules/</code></td><td>uview-ui 2.0.38（本地迁移版）+ xe-upload 1.0.2</td></tr><tr><td><code>docs/</code></td><td>项目内历史文档（已迁入本站，后续改为指向站点链接）</td></tr><tr><td><code>nativeplugins/</code></td><td>App 原生插件（当前仅 google-services.json）</td></tr><tr><td><code>keystone_public/</code></td><td>发版归档：签名 / 安装包 / 截图 / 软著 / 账号资料（gitignore，不入库）</td></tr></tbody></table><h2 id="分包策略-重点" tabindex="-1">分包策略（重点） <a class="header-anchor" href="#分包策略-重点" aria-label="Permalink to &quot;分包策略（重点）&quot;">​</a></h2><p><strong>分包原则</strong>（README 权威表述）：控制主包 2M 以内；分包与主包内容分离；功能页面全部拆进分包，主包只保留首页、功能菜单、我的。</p><p>当前 <code>pages.json</code> 实际结构（<strong>9 个分包 / 122 页</strong>，随业务增长从早期 4 分包拆分而来）：</p><table tabindex="0"><thead><tr><th>分包 root</th><th>页数</th><th>内容</th></tr></thead><tbody><tr><td><code>subPages/main_pages</code></td><td>3</td><td>navigation（功能菜单）、mine（我的）、notice（通知）——从主包迁入以瘦身</td></tr><tr><td><code>subPages/system</code></td><td>7</td><td>login / language / privacy / project×2 / web_view / version_debug</td></tr><tr><td><code>subPages/chart_page</code></td><td>8</td><td>图表统计页（qiun-data-charts 体系）</td></tr><tr><td><code>subPages/business/personnel_mgmt</code></td><td>21</td><td>人员：登记、考试、打卡、会议等</td></tr><tr><td><code>subPages/business/qual_mgmt</code></td><td>41</td><td>质量：拌合站、试验检测 19 个模块（最大分包）</td></tr><tr><td><code>subPages/business/safe_mgmt</code></td><td>21</td><td>安全：巡检、许可、视频监控（含 3 个播放器插件页）</td></tr><tr><td><code>subPages/business/machinery_mgmt</code></td><td>16</td><td>机械：龙门架、电力、运输、车辆、维保</td></tr><tr><td><code>subPages/business/env_mgmt</code></td><td>2</td><td>环境：智能电表 / 水表</td></tr><tr><td><code>subPages/business/progress_collab</code></td><td>3</td><td>进度：形象进度填报</td></tr></tbody></table><p>主包 <code>pages/</code> 仅 3 条注册：<code>pages/index/index</code>（首页）、<code>components/pap-cascader/pap-cascader</code>（级联弹层页面承载）、<code>components/app-upgrade/index</code>（<code>#ifdef APP-PLUS</code> 条件注册的升级弹窗）。</p><div class="warning custom-block"><p class="custom-block-title">体积红线（如实记录的现状机制）</p><p>与 PC 端编译期裁剪不同，移动端页面<strong>全量打进分包</strong>，客户差异完全交给运行时权限与 prefix-rules。后果：包体积随业务只增不减，<strong>主包 2MB 是微信硬红线</strong>（当前靠 main_pages 迁包维持）；客户 A 的页面代码对客户 B 可见。分包体积监控已列入遗留项（缺口分析 §3.4）。</p></div><h2 id="pages-json-结构说明" tabindex="-1">pages.json 结构说明 <a class="header-anchor" href="#pages-json-结构说明" aria-label="Permalink to &quot;pages.json 结构说明&quot;">​</a></h2><ul><li><code>pages</code>：主包页面注册（首页必须第一条）；</li><li><code>subPackages</code>：分包注册，<code>root</code> + <code>pages[]</code>；页面 path 写全如 <code>business/qual_mgmt/cement_realtime_status/index</code>；</li><li><strong>无 tabBar</strong>：底栏由自绘组件 <code>pap-tabbar</code> 实现（全局 <code>navigationStyle: &quot;custom&quot;</code>，导航栏也是自绘 <code>pap-navbar</code>）——原生 tabBar 配置不存在，别找错了；</li><li><code>globalStyle</code>：custom 导航、标题「交付小程序」、背景 <code>#F2F3F5</code>；</li><li><code>easycom</code>：<code>&quot;^pap-(.*)&quot;: &quot;@/components/pap-$1/pap-$1.vue&quot;</code>——pap 组件免 import 直接用；</li><li><code>optimization.subPackages</code>：<code>true</code>（mp-weixin 与根级各一份），分包内组件按需打包。</li></ul><h2 id="页面三件套约定" tabindex="-1">页面三件套约定 <a class="header-anchor" href="#页面三件套约定" aria-label="Permalink to &quot;页面三件套约定&quot;">​</a></h2><p>每个业务模块（如 <code>subPages/business/personnel_mgmt/pers_reg/</code>）统一：</p><ul><li><code>index.vue</code>：列表主页（统一命名，不叫 list.vue）；</li><li><code>detail.vue</code> / <code>edit.vue</code>：详情与编辑（按需）；</li><li><code>lang.js</code>：本模块 i18n 词条（并入 AppLang 聚合）；</li><li><code>api.js</code>（可选）：本模块接口。</li></ul><p>新增页面/模块的逐步操作见<a href="./function-development.html">功能开发</a>。</p><hr><p><strong>负责人</strong>：E9 前端团队 ｜ <strong>最后验证日期</strong>：2026-09-16 ｜ <strong>对应蓝本项目</strong>：<code>delivery-template-uniapp</code></p>',18)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
